Change(genesis='e30427e699992327267add669c3bc989f6d16525ba6f493121eec7778638e0ce', deps=('f558be415cae7d3559548af0e3eea6162a2987417f767c925405737385f9c38e',), event=Authored(todo='lazysync', at=datetime(2026, 11, 25, 1, 33, 45, 735243), actor='bmabsout', kind='suzateryTodo', created=datetime(2026, 10, 17, 0, 0, 0), body="Lazy sync by hash: a small eager skeleton (the DAG of hashes and headers, each with its size), content fetched on demand by hash, cached as immutable on the box and in IndexedDB, prefetched by recency, folds memoised per node; the tab sums the sizes it lacks and shows the pull as a progress bar (bytes done of bytes needed, per store), and today's whole-store pulls report their total size with the first piece so the bar works before the later stages.", spec=Flat(value=0.7), rationale=('A device should fetch what it draws and show how much is left, not pull every store whole.',), category='', waiting_on='localwrites', detail="The task coldsyncslow waits on this one; its library half is the item lazy-content-by-hash of the library's own roadmap.\n\n2026-11-25, release 2.1.253, deployed: the conversations' list is read by titles. On a device that holds nothing it stands on the skeleton and fills each row in place as its few lines land, each row saying what it still lacks; a search over part of the content says how many conversations it read of how many and reads more as content lands. On the generated large store over a phone's network the list is drawn in about five seconds where it took about fifty. Left for a later stage: turns that say no words other than the box's notes still cost a fetch each on the walk to a row's last words, which needs the skeleton to tell them apart.", source=None, subtodos=(), notes=(), note=''))